import unittest

from names import join_names


class JoinNamesTests(unittest.TestCase):
    def test_empty(self):
        self.assertEqual(join_names([]), "")

    def test_one(self):
        self.assertEqual(join_names(["Ann"]), "Ann")

    def test_many(self):
        self.assertEqual(join_names(["Ann", "Bo", "Cy"]), "Ann, Bo and Cy")


if __name__ == "__main__":
    unittest.main()

